-- Tables with many column features, constraints and comments.
CREATE TABLE app.authors (
  id bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000 INCREMENT BY 10) PRIMARY KEY,
  user_id uuid REFERENCES auth.users (id) ON DELETE SET NULL,
  handle app.slug NOT NULL UNIQUE,
  name text COLLATE "C" NOT NULL,
  address app.address,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.articles (
  id serial PRIMARY KEY,
  author_id bigint NOT NULL,
  title text NOT NULL,
  status app.status NOT NULL DEFAULT 'draft',
  word_count app.positive_int,
  price numeric(10, 2) CHECK (price >= 0),
  price_with_tax numeric GENERATED ALWAYS AS (price * 1.2) STORED,
  tags text[] DEFAULT '{}',
  during tstzrange,
  CONSTRAINT articles_author_fk FOREIGN KEY (author_id) REFERENCES app.authors (id)
    ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT no_overlap EXCLUDE USING gist (author_id WITH =, during WITH &&)
);
ALTER TABLE app.articles REPLICA IDENTITY FULL;
ALTER TABLE app.articles ADD CONSTRAINT title_not_blank CHECK (length(title) > 0) NOT VALID;
COMMENT ON TABLE app.articles IS 'Articles written by authors';
COMMENT ON COLUMN app.articles.title IS 'Headline; must not be blank';

CREATE SEQUENCE app.custom_seq START WITH 100;
CREATE TABLE app.counters (n integer NOT NULL DEFAULT nextval('app.custom_seq'));
ALTER SEQUENCE app.custom_seq OWNED BY app.counters.n;

CREATE TABLE "App Data"."User Settings" (
  "Id" int PRIMARY KEY,
  "Dark.Mode" boolean DEFAULT false,
  payload jsonb
);

CREATE TABLE app.events (
  id bigint NOT NULL,
  happened_at date NOT NULL,
  payload jsonb
) PARTITION BY RANGE (happened_at);
CREATE TABLE app.events_2026 PARTITION OF app.events FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE TABLE app.events_default PARTITION OF app.events DEFAULT;
ALTER TABLE app.events ADD PRIMARY KEY (id, happened_at);

CREATE TABLE app.base_log (id int, msg text);
CREATE TABLE app.audit_log (actor text) INHERITS (app.base_log);
CREATE UNLOGGED TABLE app.scratch (k text PRIMARY KEY, v text) WITH (fillfactor = 70);
